head.script:
scwin.gVar = {
    "cTabIndexTarget" : "",
    "cTabIndexInput" : "",
    "cTabIndexButton" : "",
    "cTabIndexSelectBox" : "",
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 기존 input2 있으면 삭제
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    // 기존 button2 있으면 삭제
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    // 기존 selectbox2 있으면 삭제
    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    // 조건 설정 (target)
    let properties = {
        tabIndex: scwin.gVar["cTabIndexTarget"],
    };

    let cList = $c.gcm.createCList(properties);

    // 조건 설정 (input)
    let properties_input = {
        tabIndex: scwin.gVar["cTabIndexInput"],
    };

    let cList_input = $c.gcm.createCList(properties_input);

    // 조건 설정 (button)
    let properties_button = {
        tabIndex: scwin.gVar["cTabIndexButton"],
    };

    let cList_button = $c.gcm.createCList(properties_button);

    // 조건 설정 (selectbox)
    let properties_selectbox = {
        tabIndex: scwin.gVar["cTabIndexSelectBox"],
    };

    let cList_selectbox = $c.gcm.createCList(properties_selectbox);

    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    // 보조 컴포넌트(input2, button2, selectbox2)를 먼저 생성한 후 target(searchbox) 생성
    await $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");
    await $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");
    await $c.gcm.createBasicSelectBox(cList_selectbox, 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");
    await $c.gcm.createBasicSearchBox(cList, 'ev:onfocus="scwin.target1_onfocus"');

    target1.setValue("target");
    input2.setValue("input");
    scwin.changeDisplay();
}



scwin.changeDisplay = function() {
    // ID에 "target1"을 포함하는 요소 선택
    var elements = document.querySelectorAll('[id*="target1"]');

    // 선택된 모든 요소에 대해 display 속성 변경
    elements.forEach(function(element) {
        element.style.display = 'block';
    });
}
